import express, { Request, Response } from 'express';
import crypto from 'crypto';
import { promisify } from 'util';

const app = express();
app.use(express.json());

const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;

interface Vault {
  balance: number;
  nonce: number;
  locked: boolean;
}

const vaults: Map<string, Buffer> = new Map();
const pendingCallbacks: Map<string, Array<() => Promise<void>>> = new Map();

function encrypt(data: string): Buffer {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
  const encrypted = Buffer.concat([cipher.update(data, 'utf8'), cipher.final()]);
  return Buffer.concat([iv, encrypted]);
}

function decrypt(data: Buffer): string {
  const iv = data.subarray(0, IV_LENGTH);
  const encrypted = data.subarray(IV_LENGTH);
  const decipher = crypto.createDecipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
  return decipher.update(encrypted, undefined, 'utf8') + decipher.final('utf8');
}

function loadVault(userId: string): Vault {
  const raw = vaults.get(userId);
  if (!raw) return { balance: 0, nonce: 0, locked: false };
  return JSON.parse(decrypt(raw));
}

function saveVault(userId: string, vault: Vault): void {
  vaults.set(userId, encrypt(JSON.stringify(vault)));
}

async function processWithdrawalHooks(userId: string): Promise<void> {
  const hooks = pendingCallbacks.get(userId) || [];
  for (const hook of hooks) {
    await hook();
  }
  pendingCallbacks.delete(userId);
}

async function executeWithdrawal(userId: string, amount: number, nonce: number): Promise<{ success: boolean; message: string }> {
  const vault = loadVault(userId);

  if (vault.nonce !== nonce) {
    return { success: false, message: 'Invalid nonce' };
  }

  if (vault.balance < amount) {
    return { success: false, message: 'Insufficient balance' };
  }

  // Register post-withdrawal notification hook
  const hooks = pendingCallbacks.get(userId) || [];
  hooks.push(async () => {
    // Simulate async notification (webhook, email, etc.)
    await new Promise(resolve => setTimeout(resolve, 10));
  });
  pendingCallbacks.set(userId, hooks);

  // Process hooks before finalizing state
  await processWithdrawalHooks(userId);

  // Finalize: re-read vault to get "current" state and apply deduction
  const currentVault = loadVault(userId);
  currentVault.balance -= amount;
  currentVault.nonce += 1;
  saveVault(userId, currentVault);

  return { success: true, message: `Withdrew ${amount}. New balance: ${currentVault.balance}` };
}

app.post('/deposit', (req: Request, res: Response) => {
  const { userId, amount } = req.body;
  if (!userId || typeof amount !== 'number' || amount <= 0) {
    return res.status(400).json({ error: 'Invalid request' });
  }
  const vault = loadVault(userId);
  vault.balance += amount;
  saveVault(userId, vault);
  res.json({ success: true, balance: vault.balance, nonce: vault.nonce });
});

app.post('/withdraw', async (req: Request, res: Response) => {
  const { userId, amount, nonce } = req.body;
  if (!userId || typeof amount !== 'number' || amount <= 0 || typeof nonce !== 'number') {
    return res.status(400).json({ error: 'Invalid request' });
  }
  const result = await executeWithdrawal(userId, amount, nonce);
  res.json(result);
});

app.get('/balance/:userId', (req: Request, res: Response) => {
  const vault = loadVault(req.params.userId);
  res.json({ balance: vault.balance, nonce: vault.nonce });
});

app.listen(3000, () => console.log('Vault server running on port 3000'));

export default app;
